(a.order_status) =\'freereplacement\' then \'freereplacement\' when lower(a.report_type) = \'amazon return\' and lower(a.order_status) =\'refund\' then \'return\' when lower(a.report_type) = \'amazon sales\' and lower(a.order_status) =\'cancel\' then \'amazon cancel\' when lower(a.report_type) = \'amazon sales\' and lower(a.order_status) =\'shipment\' then \'shipped\' when lower(a.report_type) = \'easyecom yfl return\' and lower(a.order_status) =\'cancelled\' then \'return\' when lower(a.report_type) = \'easyecom yfl return\' and lower(a.order_status) =\'returned\' then \'return\' when lower(a.report_type) = \'easyecom yfl return\' and lower(a.order_status) =\'shipped\' then \'return\' when lower(a.report_type) = \'easyecom yfl sale\' and lower(a.order_status) =\'cancelled\' then \'ee cancel\' when lower(a.report_type) = \'easyecom yfl sale\' and lower(a.order_status) =\'confirmed\' then \'confirmed\' when lower(a.report_type) = \'easyecom yfl sale\' and lower(a.order_status) =\'manifest scanned\' then \'manifest scanned\' when lower(a.report_type) = \'easyecom yfl sale\' and lower(a.order_status) =\'on hold\' then \'on hold\' when lower(a.report_type) = \'easyecom yfl sale\' and lower(a.order_status) =\'printed\' then \'printed\' when lower(a.report_type) = \'easyecom yfl sale\' and lower(a.order_status) =\'returned\' then \'ee sale return\' when lower(a.report_type) = \'easyecom yfl sale\' and lower(a.order_status) =\'shipped\' then \'shipped\' else null end as new_status from hox_db.maplemonk.HOX_yfl_sevenchef_Tax_consolidated_report_intermediate a left join hox_db.maplemonk.HOX_YFL_packaging_material b on a.REFERENCE_CODE = b.REFERENCE_CODE and lower(a.marketplace) = lower(b.marketplace) and lower(a.report_type) = lower(b.report_type) and lower(a.sku) = lower(b.sku) )as o ) select o.*, coalesce(gross_quantity,0) - coalesce(return_quantity,0) as net_quantity, coalesce(gross_abs_invoice_amt,0) - coalesce(return_SP,0) as net_revenue, coalesce(gross_abs_taxable_value, 0) - coalesce(return_abs_taxable_value, 0) as net_taxable_value from ( select *, case when lower(REPORT_TYPE) in (\'easyecom yfl sale\', \'amazon sales\') then QUANTITY else 0 end as gross_quantity, case when lower(REPORT_TYPE) in (\'easyecom yfl sale\', \'amazon sales\') then ABSOLUTE_INVOICE_AMOUNT else 0 end as gross_abs_invoice_amt, case when lower(REPORT_TYPE) in (\'easyecom yfl sale\', \'amazon sales\') then SELLING_PRICE else 0 end as gross_SP, case when lower(REPORT_TYPE) in (\'easyecom yfl sale\', \'amazon sales\') then ABS_TAX_EXCLUSIVE_GROSS else 0 end as gross_abs_taxable_value, case when lower(REPORT_TYPE) in (\'easyecom yfl return\', \'amazon sales\', \'amazon return\') and lower(new_status) in (\'return\', \'amazon cancel\', \'ee cancel\') then new_quantity else 0 end as return_quantity, case when lower(REPORT_TYPE) in (\'easyecom yfl return\', \'amazon sales\', \'amazon return\') and lower(new_status) in (\'return\', \'amazon cancel\', \'ee cancel\') then new_abs_invoice_amt else 0 end as return_abs_invoice_amt, case when lower(REPORT_TYPE) in (\'easyecom yfl return\', \'amazon sales\', \'amazon return\') and lower(new_status) in (\'return\', \'amazon cancel\', \'ee cancel\') then new_selling_price else 0 end as return_SP, case when lower(REPORT_TYPE) in (\'easyecom yfl return\', \'amazon sales\', \'amazon return\') and lower(new_status) in (\'return\', \'amazon cancel\', \'ee cancel\') then new_abs_tax_exclusive_gross else 0 end as return_abs_taxable_value from abc )as o",
